insert into kb.articles(article_id,version,title,categories,publisher,scope,kind,status,reference_url,checked_on,review_due) values
  ('savings-fees',1,'Savings account fees',array['retail'],'DemoBank coursework project','Fictional demo guidance; not a live bank policy.','demo','published',null,null,null),
  ('app-login-recovery',1,'Mobile app login recovery',array['retail','fraud'],'DemoBank coursework project','Fictional demo guidance; not a live bank policy.','demo','published',null,null,null),
  ('car-loans',1,'Car loans',array['retail'],'DemoBank coursework project','Fictional demo guidance; not a live bank policy.','demo','published',null,null,null),
  ('unrecognised-charge',1,'Unrecognised card charge',array['fraud'],'DemoBank coursework project','Fictional demo guidance; not a live bank policy.','demo','published',null,null,null);
insert into kb.sections(article_id,version,anchor,heading,body,keywords) values
  ('savings-fees',1,'main','Savings account fees','The fictional DemoBank Everyday Savings account has no monthly account fee (SGD 0). A fall-below fee of SGD 2 per month applies when the average daily balance in a month is below SGD 1,000. These are synthetic demo terms, not a live bank price list.','savings saving acc account monthly fee fees charge fall-below minimum balance'),
  ('app-login-recovery',1,'steps','Mobile app login recovery','If you are locked out of the mobile app: 1. Close and reopen the official app and check that it is updated. 2. On the sign-in screen choose Forgot password and follow the steps; a one-time code is sent only to your registered phone. 3. Enter that code only in the official app, never in chat, email or a phone call. 4. If the app says your access is locked after several attempts, wait for the stated time or use the official app''s Help service to unlock it. 5. If you did not try to sign in yourself, treat it as a security issue and contact your bank through its official app or website. This chat never needs your password, PIN or one-time code.','locked locked out lockout app mobile phone login log in sign in forgot password unlock access'),
  ('car-loans',1,'products','Car loan products','The fictional DemoBank offers car loans for new and used cars, repaid in fixed monthly instalments over an agreed term. A car loan is usually secured on the car. Interest rates, fees and maximum loan amounts are not supplied in this demo.','car loan auto vehicle new used instalment'),
  ('car-loans',1,'eligibility','General car loan eligibility','Applicants generally need to be at least 21 years old, have a regular income and provide identification and proof of income. Meeting these general points does not mean an application will be approved. The bank makes the final decision on every application after its own checks.','car loan eligibility eligible income age approve approval'),
  ('car-loans',1,'apply','How to apply for a car loan','Apply through the official DemoBank app or website under Loans, then Car loan, or ask a relationship manager. The chatbot cannot submit an application or promise approval. This is general information, not advice or a contract.','car loan apply application channel'),
  ('unrecognised-charge',1,'urgent-steps','Urgent steps for an unrecognised charge','If you do not recognise a card charge, act now: 1. Contact your bank immediately through the official fraud line printed on the back of your card or the report function in its official app. 2. Ask for the card to be blocked if it may be compromised. 3. Check your other recent transactions. 4. Never share your PIN, password, one-time code or full card number. In this demo the assistant can offer a temporary block of a synthetic card, which runs only after you confirm it. It cannot investigate, dispute or reverse a charge.','unrecognised unrecognized unfamiliar charge fraud suspicious transaction dont recognise not mine block'),
  ('unrecognised-charge',1,'replacement-card','Replacement card after a block','A temporary block stops new card payments but does not cancel the card or reverse any charge. Identity verification and permanent cancellation are done by bank staff. After staff confirm the card should be cancelled, the bank issues a replacement card with a new number to your registered address.','replacement card new card block cancel cancellation verification');
insert into kb.articles(article_id,version,title,categories,publisher,scope,kind,status,reference_url,checked_on,review_due) values
  ('lost-card',2,'Lost or stolen card guidance',array['fraud'],'DemoBank coursework project','Fictional demo guidance; not a live bank policy.','demo','published',null,null,null),
  ('support',2,'Getting human support',array['retail','fraud','compliance','document','relationship'],'DemoBank coursework project','Fictional demo guidance; not a live bank policy.','demo','published',null,null,null);
insert into kb.sections(article_id,version,anchor,heading,body,keywords) values
  ('lost-card',2,'main','Lost or stolen card guidance','Report a lost or stolen card to your bank immediately through its official app or website. If the official app offers a freeze or block control, use that control. The chatbot cannot block a card from this reply. For a suspicious charge in your signed-in synthetic records it can offer a temporary block, which runs only after you confirm it; it cannot cancel a card permanently. Review recent activity and report unfamiliar transactions. Do not wait for a reply here if your real card is at risk. Never share your PIN, password, OTP, CVV or full card number.','lost stolen missing card block freeze'),
  ('support',2,'main','Getting human support','When you are signed in, Talk to a person shows a short summary; approving it records a support handoff for staff in this demo. The demo has no staffed queue, so no person will reply. As a guest you can review, edit and copy a summary for your own use; copying does not send anything. For a real issue, contact your bank using its official app or website. The chatbot cannot make payments, close accounts, dispute charges or change banking records.','human person support staff contact close dispute transfer refund handoff');
